    /* ===========================================
       === SLIDE PRESENTATION CONTROLLER ===
       Zero-dependency navigation + animations
       =========================================== */

    class SlidePresentation {
      constructor() {
        this.slides = Array.from(document.querySelectorAll('.slide'));
        this.nav = document.getElementById('nav');
        this.progress = document.getElementById('progress');
        this.current = 0;
        this.isScrolling = false;

        this.buildNav();
        this.bindEvents();
        this.observeSlides();
        this.updateUI();
      }

      buildNav() {
        this.nav.innerHTML = '';
        this.dots = this.slides.map((slide, i) => {
          const dot = document.createElement('div');
          dot.className = 'nav-dot';
          dot.title = slide.dataset.title || `Slide ${i + 1}`;
          dot.addEventListener('click', () => this.goTo(i));
          this.nav.appendChild(dot);
          return dot;
        });
      }

      bindEvents() {
        window.addEventListener('keydown', (e) => {
          if (['ArrowDown', 'PageDown', ' '].includes(e.key)) {
            e.preventDefault();
            this.next();
          }
          if (['ArrowUp', 'PageUp'].includes(e.key)) {
            e.preventDefault();
            this.prev();
          }
        }, { passive: false });

        let touchY = null;
        window.addEventListener('touchstart', (e) => {
          touchY = e.touches?.[0]?.clientY ?? null;
        }, { passive: true });

        window.addEventListener('touchend', (e) => {
          if (touchY === null) return;
          const endY = e.changedTouches?.[0]?.clientY ?? touchY;
          const dy = endY - touchY;
          if (Math.abs(dy) > 40) {
            dy < 0 ? this.next() : this.prev();
          }
          touchY = null;
        }, { passive: true });

        window.addEventListener('wheel', (e) => {
          if (this.isScrolling) return;
          if (Math.abs(e.deltaY) < 12) return;
          this.isScrolling = true;
          e.deltaY > 0 ? this.next() : this.prev();
          setTimeout(() => { this.isScrolling = false; }, 420);
        }, { passive: true });

        window.addEventListener('scroll', () => {
          // Track current slide based on scroll position
          const y = window.scrollY;
          const idx = Math.round(y / window.innerHeight);
          const clamped = Math.max(0, Math.min(this.slides.length - 1, idx));
          if (clamped !== this.current) {
            this.current = clamped;
            this.updateUI();
          }
        }, { passive: true });
      }

      observeSlides() {
        const io = new IntersectionObserver((entries) => {
          for (const entry of entries) {
            if (entry.isIntersecting) {
              entry.target.classList.add('visible');
            }
          }
        }, { threshold: 0.4 });

        this.slides.forEach(s => io.observe(s));
      }

      goTo(index) {
        const i = Math.max(0, Math.min(this.slides.length - 1, index));
        this.current = i;
        this.slides[i].scrollIntoView({ behavior: 'smooth', block: 'start' });
        this.updateUI();
      }

      next() { this.goTo(this.current + 1); }
      prev() { this.goTo(this.current - 1); }

      updateUI() {
        this.dots.forEach((d, i) => d.classList.toggle('active', i === this.current));
        const pct = ((this.current) / (this.slides.length - 1)) * 100;
        this.progress.style.width = `${pct}%`;

        // Update any pagers found
        const label = String(this.current + 1).padStart(2, '0') + ' / ' + String(this.slides.length).padStart(2, '0');
        document.querySelectorAll('[id^="pager"]').forEach(el => el.textContent = label);
      }
    }

    window.addEventListener('DOMContentLoaded', () => {
      new SlidePresentation();
      // Ensure first slide is visible for initial render
      document.querySelector('.slide')?.classList.add('visible');
    });
  </script>
