      font-size: var(--small-size);
      color: rgba(255,255,255,0.72);
      line-height: 1.35;
    }

    .pill {
      display: inline-flex;
      align-items: center;
      gap: 0.5ch;
      padding: clamp(0.25rem, 0.6vw, 0.4rem) clamp(0.5rem, 1.2vw, 0.85rem);
      border-radius: 999px;
      border: 1px solid rgba(255,255,255,0.18);
      background: rgba(255,255,255,0.06);
      font-family: var(--font-mono);
      font-size: clamp(0.62rem, 0.95vw, 0.85rem);
      letter-spacing: 0.02em;
      color: rgba(255,255,255,0.82);
      white-space: nowrap;
    }

    .pill .swatch {
      width: 0.7em;
      height: 0.7em;
      border-radius: 999px;
      background: var(--accent-blue);
      box-shadow: 0 0 0 2px rgba(255,255,255,0.14);
    }

    .bullets {
      margin: 0;
      padding-left: clamp(1.1rem, 2.2vw, 1.8rem);
      display: grid;
      gap: clamp(0.4rem, 1vh, 0.85rem);
    }

    .bullets li {
      font-size: var(--body-size);
      line-height: 1.35;
      color: rgba(255,255,255,0.88);
    }

    .muted {
      color: rgba(255,255,255,0.72);
    }

    /* ===========================================
       === CHARTS / FIGURES ===
       =========================================== */

    .chart {
      display: flex;
      flex-direction: column;
      gap: clamp(0.55rem, 1.4vw, 1rem);
    }

    .barrow {
      display: grid;
      grid-template-columns: minmax(140px, 220px) 1fr minmax(60px, 110px);
      gap: clamp(0.6rem, 1.4vw, 1rem);
      align-items: center;
    }

    .barlabel {
      font-size: clamp(0.75rem, 1.25vw, 1rem);
      color: rgba(255,255,255,0.85);
      font-weight: 700;
      letter-spacing: 0.01em;
    }

    .barwrap {
      height: clamp(0.55rem, 1.2vw, 0.95rem);
      border-radius: 999px;
      background: rgba(255,255,255,0.08);
      border: 1px solid rgba(255,255,255,0.12);
      overflow: hidden;
      position: relative;
    }

    .bar {
      height: 100%;
      width: var(--w);
      border-radius: 999px;
      background: linear-gradient(90deg, rgba(67,97,238,0.85), rgba(45,212,191,0.85));
      box-shadow: 0 0 0 1px rgba(255,255,255,0.12) inset;
    }

    .barrow.highlight .barwrap {
      background: rgba(245, 158, 11, 0.10);
      border-color: rgba(245, 158, 11, 0.34);
      box-shadow: 0 0 0 1px rgba(245, 158, 11, 0.20) inset, 0 0 28px rgba(245, 158, 11, 0.18);
    }

    .barrow.highlight .bar {
      background: linear-gradient(90deg, rgba(245,158,11,0.95), rgba(251,113,133,0.92));
    }

    .baryears {
      font-family: var(--font-mono);
      font-size: clamp(0.65rem, 1vw, 0.9rem);
      color: rgba(255,255,255,0.72);
      text-align: right;
      white-space: nowrap;
    }

    .legend {
      display: flex;
      flex-wrap: wrap;
      gap: clamp(0.35rem, 1vw, 0.8rem);
      align-items: center;
    }

    .legend .pill .swatch { background: linear-gradient(135deg, var(--accent-cyan), var(--accent-blue)); }
    .legend .pill.gold .swatch { background: linear-gradient(135deg, var(--accent-amber), var(--accent-rose)); }

    /* ===========================================
       === TABLE ===
       =========================================== */

    table {
      width: 100%;
      border-collapse: collapse;
      font-size: clamp(0.62rem, 1vw, 0.92rem);
      line-height: 1.25;
      overflow: hidden;
      border-radius: clamp(0.8rem, 1.5vw, 1.2rem);
      border: 1px solid rgba(255,255,255,0.14);
    }

    thead th {
      text-align: left;
      font-family: var(--font-mono);
      letter-spacing: 0.02em;
      font-size: clamp(0.6rem, 0.95vw, 0.82rem);
      color: rgba(255,255,255,0.78);
      background: rgba(255,255,255,0.06);
      padding: clamp(0.45rem, 1vw, 0.85rem);
      border-bottom: 1px solid rgba(255,255,255,0.14);
      white-space: nowrap;
    }

    tbody td {
      padding: clamp(0.45rem, 1vw, 0.85rem);
      border-bottom: 1px solid rgba(255,255,255,0.10);
      vertical-align: top;
      color: rgba(255,255,255,0.88);
    }

    tbody tr:last-child td { border-bottom: none; }

    .tag {
      display: inline-flex;
      align-items: center;
      gap: 0.45ch;
      padding: 0.2em 0.55em;
      border-radius: 999px;
      font-family: var(--font-mono);
      font-size: clamp(0.58rem, 0.9vw, 0.78rem);
      letter-spacing: 0.02em;
      white-space: nowrap;
      border: 1px solid rgba(255,255,255,0.18);
      background: rgba(255,255,255,0.06);
      color: rgba(255,255,255,0.82);
    }

    .tag.full {
      border-color: rgba(45, 212, 191, 0.38);
      background: rgba(45, 212, 191, 0.14);
      color: rgba(216, 255, 249, 0.95);
    }

    /* ===========================================
       === HEATMAP MOCK ===
       =========================================== */

    .heatmap-wrap {
      display: grid;
      grid-template-columns: 1fr;
      gap: clamp(0.6rem, 1.4vw, 1.2rem);
      align-items: start;
    }

    .heatmap-img {
      border-radius: clamp(0.8rem, 1.4vw, 1.2rem);
      border: 1px solid rgba(255,255,255,0.14);
      overflow: hidden;
      background: rgba(255,255,255,0.04);
    }

    .heatmap-img img {
      width: 100%;
      height: auto;
      max-height: min(46vh, 520px);
      object-fit: cover;
      display: block;
    }

    .milestones {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: clamp(0.5rem, 1.2vw, 1rem);
    }

    .milestone {
      border-radius: clamp(0.8rem, 1.2vw, 1rem);
      border: 1px solid rgba(255,255,255,0.14);
      background: rgba(255,255,255,0.05);
      padding: clamp(0.6rem, 1.3vw, 1rem);
    }

    .milestone .year {
      font-family: var(--font-mono);
      font-size: clamp(0.75rem, 1.2vw, 1rem);
      color: rgba(255,255,255,0.78);
    }

    .milestone .txt {
      margin-top: 0.35rem;
      font-size: clamp(0.72rem, 1.15vw, 0.98rem);
      color: rgba(255,255,255,0.90);
      line-height: 1.25;
    }

    /* ===========================================
       === HERD IMMUNITY DIAGRAM ===
       =========================================== */

    .diagram {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: clamp(0.8rem, 2vw, 1.6rem);
      align-items: center;
    }

    .diagram-panel {
      border-radius: clamp(0.9rem, 1.6vw, 1.3rem);
      border: 1px solid rgba(255,255,255,0.14);
      background: rgba(255,255,255,0.05);
      padding: clamp(0.8rem, 1.8vw, 1.4rem);
      overflow: hidden;
    }

    .people {
      display: grid;
      grid-template-columns: repeat(6, 1fr);
      gap: clamp(0.25rem, 0.7vw, 0.55rem);
      align-items: center;
      justify-items: center;
    }

    .person {
      width: clamp(0.55rem, 1.4vw, 0.95rem);
      height: clamp(0.55rem, 1.4vw, 0.95rem);
      border-radius: 999px;
      background: rgba(255,255,255,0.20);
      box-shadow: 0 0 0 1px rgba(255,255,255,0.10) inset;
      position: relative;
    }

    .person.vax { background: rgba(67, 97, 238, 0.85); }
    .person.vax::after {
      content: '';
      position: absolute;
      inset: -22%;
      border-radius: 999px;
      border: 1px solid rgba(67, 97, 238, 0.35);
      box-shadow: 0 0 18px rgba(67,97,238,0.18);
    }

    .person.vuln { background: rgba(251, 113, 133, 0.92); }
    .person.path { background: rgba(245, 158, 11, 0.95); }

    .arrow {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 0.6rem;
      padding: 0.6rem 0;
      font-family: var(--font-mono);
      font-size: clamp(0.65rem, 1vw, 0.9rem);
      color: rgba(255,255,255,0.76);
    }

    .arrow .line {
      height: 2px;
      width: min(10vw, 120px);
      background: rgba(255,255,255,0.22);
      position: relative;
      border-radius: 999px;
    }

    .arrow .line::after {
      content: '';
      position: absolute;
      right: -2px;
      top: 50%;
      width: 10px;
      height: 10px;
      transform: translateY(-50%) rotate(45deg);
      border-right: 2px solid rgba(255,255,255,0.30);
      border-top: 2px solid rgba(255,255,255,0.30);
    }

    /* ===========================================
       === ANIMATION ===
       =========================================== */

    .reveal {
      opacity: 0;
      transform: translateY(clamp(10px, 1.6vh, 18px));
      transition: opacity 700ms ease, transform 900ms cubic-bezier(0.16, 1, 0.3, 1);
    }

    .slide.visible .reveal {
      opacity: 1;
      transform: translateY(0);
    }

    .delay-1 { transition-delay: 120ms; }
    .delay-2 { transition-delay: 220ms; }
    .delay-3 { transition-delay: 320ms; }
    .delay-4 { transition-delay: 420ms; }

    /* ===========================================
       === NAV DOTS / PROGRESS ===
       =========================================== */

    .nav-dots {
      position: fixed;
      right: clamp(0.8rem, 2vw, 1.3rem);
      top: 50%;
      transform: translateY(-50%);
      display: flex;
      flex-direction: column;
      gap: clamp(0.35rem, 0.9vw, 0.6rem);
      z-index: 999;
    }

    .nav-dot {
      width: clamp(8px, 0.9vw, 12px);
      height: clamp(8px, 0.9vw, 12px);
      border-radius: 999px;
      background: rgba(255,255,255,0.22);
      border: 1px solid rgba(255,255,255,0.18);
      cursor: pointer;
      transition: transform 200ms ease, background 200ms ease;
    }

    .nav-dot.active {
      background: linear-gradient(135deg, var(--accent-cyan), var(--accent-blue));
      transform: scale(1.25);
    }

    .progress {
      position: fixed;
      left: 0;
      bottom: 0;
      height: 4px;
      width: 0;
      background: linear-gradient(90deg, var(--accent-blue), var(--accent-cyan), var(--accent-amber));
      z-index: 999;
      transition: width 260ms ease;
    }

    .keyboard-hint {
      position: fixed;
      left: clamp(0.8rem, 2vw, 1.3rem);
      bottom: clamp(0.8rem, 2vw, 1.3rem);
      font-family: var(--font-mono);
      font-size: clamp(0.62rem, 0.95vw, 0.85rem);
      color: rgba(255,255,255,0.62);
      letter-spacing: 0.02em;
      z-index: 999;
      user-select: none;
    }

    /* Layout helpers */
    .slide-header {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: clamp(0.9rem, 2vw, 1.5rem);
    }

    .slide-header .titleblock {
      display: grid;
      gap: clamp(0.4rem, 0.9vw, 0.75rem);
    }

    .slide-header .titleblock .kicker {
      font-family: var(--font-mono);
      letter-spacing: 0.03em;
      text-transform: uppercase;
      font-size: clamp(0.65rem, 0.95vw, 0.85rem);
      color: rgba(255,255,255,0.72);
    }

    .footnote {
      margin-top: clamp(0.7rem, 1.4vw, 1.1rem);
      font-size: clamp(0.6rem, 0.95vw, 0.85rem);
      color: rgba(255,255,255,0.68);
      line-height: 1.35;
    }

    /* Ensure panels remain readable on smaller screens */
    @media (max-width: 900px) {
      .two-col { grid-template-columns: 1fr; }
      .diagram { grid-template-columns: 1fr; }
      .milestones { grid-template-columns: 1fr; }
    }
  </style>
</head>
<body>
  <div class="progress" id="progress"></div>
  <div class="nav-dots" id="nav"></div>
  <div class="keyboard-hint">Navigate: ↑ ↓ ← → / Space</div>

  <!-- =====================================================
       SLIDE 1: TITLE
       ===================================================== -->
  <section class="slide" id="title-slide" data-title="Title">
    <div class="deck-meta">
      <div class="brand"><span class="dot"></span> Vaccination Impact Brief</div>
      <div class="pager" id="pager">01 / 08</div>
    </div>
    <div class="slide-content">
      <div class="panel">
        <div class="reveal">
          <div class="legend" style="margin-bottom: var(--content-gap);">
            <span class="pill"><span class="swatch"></span> Data-forward</span>
            <span class="pill"><span class="swatch" style="background: var(--accent-cyan);"></span> Policy-relevant</span>
            <span class="pill"><span class="swatch" style="background: var(--accent-amber);"></span> 1796–2020</span>
          </div>
          <h1>The Power of Vaccination:<br/>From Smallpox Eradication to COVID-19 in Record Time</h1>
        </div>
        <div class="reveal delay-2" style="margin-top: var(--content-gap);">
          <div class="subtitle">A data-driven overview of how vaccines have transformed public health by eliminating or drastically reducing deadly diseases over the past two centuries.</div>
        </div>
        <div class="reveal delay-3" style="margin-top: var(--content-gap); display: flex; align-items: center; justify-content: space-between; gap: 1rem; flex-wrap: wrap;">
          <div class="small">Audience: public health professionals and policy analysts</div>
          <div class="small">Source: Our World in Data (ourworldindata.org/vaccination)</div>
        </div>
      </div>
    </div>
  </section>

  <!-- =====================================================
       SLIDE 2: VACCINE TIMELINE ACCELERATION
       ===================================================== -->
  <section class="slide" id="vaccine-timeline-acceleration" data-title="Timeline">
    <div class="deck-meta">
      <div class="brand"><span class="dot"></span> Pathogen → Licensure</div>
      <div class="pager" id="pager2">02 / 08</div>
    </div>
    <div class="slide-content">
      <div class="panel">
        <div class="slide-header">
          <div class="titleblock">
            <div class="kicker">Innovation pace</div>
            <h2 class="reveal">From 100 Years to Under 1 Year: Vaccine Development Is Accelerating</h2>
            <div class="small reveal delay-1">Years from pathogen identification to vaccine licensure (selected examples, 1884–2020).</div>
          </div>
          <div class="legend reveal delay-2">
            <span class="pill"><span class="swatch"></span> Typical</span>
            <span class="pill gold"><span class="swatch"></span> COVID-19 emphasized</span>
          </div>
        </div>

        <div class="chart reveal delay-2" role="img" aria-label="Horizontal bar chart showing years from pathogen identification to vaccine licensure; COVID-19 under 1 year highlighted.">
          <!-- Widths scaled to max = 105 years (Typhoid) -->
          <div class="barrow" style="--w: 100%;">
            <div class="barlabel">Typhoid fever</div>
            <div class="barwrap"><div class="bar"></div></div>
            <div class="baryears">105 years</div>
          </div>
          <div class="barrow" style="--w: 87.6%;">
            <div class="barlabel">Meningitis</div>
            <div class="barwrap"><div class="bar"></div></div>
            <div class="baryears">92 years</div>
          </div>
          <div class="barrow" style="--w: 44.8%;">
            <div class="barlabel">Polio</div>
            <div class="barwrap"><div class="bar"></div></div>
            <div class="baryears">47 years</div>
          </div>
          <div class="barrow" style="--w: 9.6%;">
            <div class="barlabel">Measles</div>
            <div class="barwrap"><div class="bar"></div></div>
            <div class="baryears">10 years</div>
          </div>
          <div class="barrow highlight" style="--w: 0.9%;">
            <div class="barlabel">COVID-19</div>
            <div class="barwrap"><div class="bar"></div></div>
            <div class="baryears">&lt;1 year</div>
          </div>
        </div>

        <div class="footnote reveal delay-3">Context: Modern tools (advanced microscopy, genome sequencing, mRNA technology, and virus-like particles) enable faster and more precise vaccine design.</div>
      </div>
    </div>
  </section>

  <!-- =====================================================
       SLIDE 3: US DISEASE ELIMINATION TABLE
       ===================================================== -->
  <section class="slide" id="us-disease-elimination" data-title="US Impact">
    <div class="deck-meta">
      <div class="brand"><span class="dot"></span> US Outcomes</div>
      <div class="pager" id="pager3">03 / 08</div>
    </div>
    <div class="slide-content">
      <div class="panel">
        <div class="slide-header">
          <div class="titleblock">
            <div class="kicker">Evidence of elimination & reduction</div>
            <h2 class="reveal">100% Case Reduction Achieved for Diphtheria, Polio, and Smallpox in the US</h2>
            <div class="small reveal delay-1">Per-million annual cases and deaths before vs. after vaccine introduction (Roush & Murphy, 2007 as cited by Our World in Data).</div>
          </div>
          <div class="kpi-card reveal delay-2" style="max-width: 320px;">
            <div class="kpi-number">3</div>
            <div class="kpi-label">Diseases with <b>100% case reduction</b> shown here</div>
          </div>
        </div>

        <div class="reveal delay-2" style="overflow: hidden;">
          <table role="table" aria-label="US vaccine-preventable disease reductions">
            <thead>
              <tr>
                <th>Disease</th>
                <th>Pre-vaccine cases<br/>(per million/yr)</th>
                <th>Post-vaccine cases<br/>(per million/yr)</th>
                <th>Case reduction</th>
                <th>Pre-vaccine deaths<br/>(per million/yr)</th>
                <th>Death reduction</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td><b>Diphtheria</b></td>
                <td>158</td>
                <td>0</td>
                <td><span class="tag full">100% (eliminated)</span></td>
                <td>13.7</td>
                <td><span class="tag full">100%</span></td>
              </tr>
              <tr>
                <td><b>Acute polio</b></td>
                <td>141</td>
                <td>0</td>
                <td><span class="tag full">100% (eliminated)</span></td>
                <td>10</td>
                <td><span class="tag full">100%</span></td>
              </tr>
              <tr>
                <td><b>Smallpox</b></td>
                <td>250</td>
                <td>0</td>
                <td><span class="tag full">100% (eliminated)</span></td>
                <td>2.9</td>
                <td><span class="tag full">100%</span></td>
              </tr>
              <tr>
                <td>Pneumococcal</td>
                <td>233</td>
                <td>139</td>
                <td>40.5%</td>
                <td>24</td>
                <td>31.3%</td>
              </tr>
              <tr>
                <td>Acute hepatitis B</td>
                <td>273</td>
                <td>44</td>
                <td>83.9%</td>
                <td>1</td>
                <td>83.6%</td>
              </tr>
            </tbody>
          </table>
        </div>

        <div class="footnote reveal delay-3">Note: Measles also shows near-elimination in cases (99.99%) with 100% death reduction; the state-level collapse is shown next.</div>
      </div>
    </div>
  </section>

  <!-- =====================================================
       SLIDE 4: MEASLES HEATMAP STATES
       ===================================================== -->
  <section class="slide" id="measles-heatmap-states" data-title="Measles">
    <div class="deck-meta">
      <div class="brand"><span class="dot"></span> Measles (States)</div>
      <div class="pager" id="pager4">04 / 08</div>
    </div>
    <div class="slide-content">
      <div class="panel">
        <div class="slide-header">
          <div class="titleblock">
            <div class="kicker">50-state shift</div>
            <h2 class="reveal">Measles Cases Collapsed Across All 50 US States After Vaccine Mandates</h2>
            <div class="small reveal delay-1">Heatmap of measles cases per 100,000 by state (1929–2022), with milestone annotations.</div>
          </div>
          <div class="kpi-card reveal delay-2" style="max-width: 360px;">
            <div class="kpi-number">1963 → 1980</div>
            <div class="kpi-label">Milestones referenced in the heatmap</div>
          </div>
        </div>

        <div class="heatmap-wrap reveal delay-2" role="img" aria-label="Measles heatmap across US states, annotated for 1963, 1971, 1980.">
          <div class="heatmap-img">
            <img src="/app/benchmark/assets/figure_2.jpg" alt="Measles heatmap across US states" />
          </div>
          <div class="milestones">
            <div class="milestone">
              <div class="year">1963</div>
              <div class="txt">First measles vaccine developed by John Enders</div>
            </div>
            <div class="milestone">
              <div class="year">1971</div>
              <div class="txt">MMR (measles-mumps-rubella) vaccine developed by Maurice Hilleman</div>
            </div>
            <div class="milestone">
              <div class="year">1980</div>
              <div class="txt">Vaccination became mandatory for children entering kindergarten</div>
            </div>
          </div>
        </div>

        <div class="footnote reveal delay-3">Before 1963, nearly every state experienced high incidence (100–1,000+ cases per 100,000). After the 1980 mandate, cases dropped to near zero across all states, with only sporadic outbreaks.</div>
      </div>
    </div>
  </section>

  <!-- =====================================================
       SLIDE 5: SMALLPOX ERADICATION STORY
       ===================================================== -->
  <section class="slide" id="smallpox-eradication-story" data-title="Smallpox">
    <div class="deck-meta">
      <div class="brand"><span class="dot"></span> Eradication</div>
      <div class="pager" id="pager5">05 / 08</div>
    </div>
    <div class="slide-content">
      <div class="panel">
        <div class="slide-header">
          <div class="titleblock">
            <div class="kicker">Global campaign</div>
            <h2 class="reveal">Smallpox: The Only Human Disease Eradicated Through Vaccination</h2>
            <div class="small reveal delay-1">Key milestones from WHO action to last natural case and certification.</div>
          </div>
          <div class="legend reveal delay-2">
            <span class="pill"><span class="swatch" style="background: var(--accent-cyan);"></span> 1959</span>
            <span class="pill"><span class="swatch" style="background: var(--accent-blue);"></span> 1967</span>
            <span class="pill"><span class="swatch" style="background: var(--accent-amber);"></span> 1977</span>
            <span class="pill"><span class="swatch" style="background: var(--accent-rose);"></span> 1980</span>
          </div>
        </div>

        <div class="two-col">
          <div class="reveal delay-2">
            <ul class="bullets">
              <li><b>1959:</b> WHO passed a resolution to eradicate smallpox.</li>
              <li><b>1967:</b> WHO launched an intensified eradication campaign.</li>
              <li><b>1977:</b> Last natural case occurred in Somalia.</li>
              <li><b>1980:</b> Smallpox declared eradicated worldwide.</li>
            </ul>
            <div class="footnote">Why eradication was possible: the virus infected only humans, symptoms were distinguishable, and the vaccine was cheap and effective.</div>
          </div>
